\begin{tikzpicture}[x=1.05cm,y=0.72cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-0.65,-3.3) rectangle (10,4.4);
\draw[->,line width=0.5pt] (-0.5,0)--(4.9,0) node[right] {$x$};
\draw[->,line width=0.5pt] (0,-3.1)--(0,4.15) node[above] {$y$};
\foreach \v in {1,2,3}{\draw[line width=0.4pt] (\v,-0.07)--(\v,0.07);\node[above] at (\v,0.1) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\foreach \v in {-1,-2}{\draw[line width=0.4pt] (-0.07,\v)--(0.07,\v);\node[left] at (-0.1,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\draw[<->,line width=0.8pt,domain=0.12:4.5,samples=180] plot (\x,{-ln(\x)/ln(3)});
\draw[<->,dashed,line width=0.8pt,domain=0.12:4.5,samples=180] plot (\x,{-2*ln(\x)/ln(3)});
\draw[<->,dotted,line width=0.8pt,domain=0.12:4.5,samples=180] plot (\x,{-ln(2*\x)/ln(3)});
\draw[line width=0.8pt] (5.4,3.1)--(6,3.1);\node[right] at (6.1,3.1) {$y=\log_{1/3}x$};
\draw[dashed,line width=0.8pt] (5.4,1.8)--(6,1.8);\node[right] at (6.1,1.8) {$y=2\log_{1/3}x$};
\draw[dotted,line width=0.8pt] (5.4,0.5)--(6,0.5);\node[right] at (6.1,0.5) {$y=\log_{1/3}(2x)$};
